package com.careerpilot.assessment;
import com.careerpilot.modules.assessment.entity.*;import com.careerpilot.modules.assessment.service.AttemptQuestionSet;import org.junit.jupiter.api.Test;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class AttemptQuestionSetTest{
 private final AttemptQuestionSet sets=new AttemptQuestionSet();
 @Test void historicalAttemptWithoutSnapshotUsesOriginalQuestionCount(){Assessment assessment=new Assessment();for(int i=1;i<=15;i++){AssessmentQuestion q=new AssessmentQuestion();q.setId(UUID.randomUUID());q.setQuestionOrder(i);assessment.getQuestions().add(q);}AssessmentAttempt historical=new AssessmentAttempt();historical.setAssessment(assessment);historical.setTotalQuestions(3);assertThat(sets.resolve(historical)).extracting(AssessmentQuestion::getQuestionOrder).containsExactly(1,2,3);}
 @Test void persistedSnapshotOverridesBankAndPreservesAttemptOrder(){Assessment assessment=new Assessment();AssessmentQuestion first=question(1),second=question(2);assessment.getQuestions().addAll(List.of(first,second));AssessmentAttempt attempt=new AssessmentAttempt();attempt.setAssessment(assessment);attempt.setTotalQuestions(2);attempt.getSelectedQuestions().add(selected(attempt,second,1));attempt.getSelectedQuestions().add(selected(attempt,first,2));assertThat(sets.resolve(attempt)).containsExactly(second,first);}
 private AssessmentQuestion question(int order){AssessmentQuestion q=new AssessmentQuestion();q.setId(UUID.randomUUID());q.setQuestionOrder(order);return q;}private AssessmentAttemptQuestion selected(AssessmentAttempt attempt,AssessmentQuestion question,int order){AssessmentAttemptQuestion value=new AssessmentAttemptQuestion();value.setAttempt(attempt);value.setQuestion(question);value.setQuestionOrder(order);return value;}
}
